#!/usr/bin/env python3
"""AI Displacement Monitor - Output Grader"""
import json
import sys
from pathlib import Path
from datetime import datetime, timedelta

MARKER = "AI_DISPLACEMENT_BENCHMARK_MARKER_7F3C"

VALID_TIERS = {"A", "B", "C"}
VALID_LIGHTS = {"GREEN", "YELLOW", "ORANGE", "RED"}
REQUIRED_INDICATORS = {"A1", "A2", "A3", "A4", "B1", "B2", "B3", "C1", "C2", "C3"}
REQUIRED_SIGNAL_FIELDS = {"id", "value", "unit", "threshold", "triggered", "trend", "timestamp"}

def load_thresholds():
    thresholds = {}
    thresh_file = Path("references/thresholds.example.json")
    if thresh_file.exists():
        data = json.loads(thresh_file.read_text())
        for ind in data.get("indicators", []):
            thresholds[ind["id"]] = ind["threshold"]
    return thresholds

def load_input(scenario_file):
    data = json.loads(Path(scenario_file).read_text())
    return data.get("series", []), data.get("asOf", "")

def validate_signal_board(signals, thresholds):
    errors = []
    found_ids = set()
    for sig in signals:
        found_ids.add(sig.get("id"))
        missing_fields = REQUIRED_SIGNAL_FIELDS - set(sig.keys())
        if missing_fields:
            errors.append(f"Signal {sig.get('id', 'unknown')} missing fields: {missing_fields}")
        if sig.get("tier") not in VALID_TIERS:
            errors.append(f"Signal {sig.get('id')} has invalid tier: {sig.get('tier')}")
    missing_ids = REQUIRED_INDICATORS - found_ids
    if missing_ids:
        errors.append(f"Missing indicators in signal board: {missing_ids}")
    return errors

def validate_composite_risk(output, series, thresholds):
    errors = []
    light = output.get("composite_risk_light")
    if light not in VALID_LIGHTS:
        errors.append(f"Invalid composite risk light: {light}")
        return errors
    tier_triggers = {"A": 0, "B": 0, "C": 0}
    for s in series:
        if s.get("value") is None:
            continue
        tid = s["id"]
        tier = tid[0]
        if s["value"] >= thresholds.get(tid, 0.5):
            tier_triggers[tier] += 1
    expected = "GREEN"
    if tier_triggers["A"] >= 2:
        expected = "YELLOW"
        if tier_triggers["B"] >= 1:
            expected = "ORANGE"
            if tier_triggers["C"] >= 1:
                expected = "RED"
    if light != expected:
        errors.append(f"Composite risk mismatch: expected {expected}, got {light}. Triggers: A={tier_triggers['A']}, B={tier_triggers['B']}, C={tier_triggers['C']}")
    return errors

def validate_actionable_notes(notes):
    errors = []
    if not isinstance(notes, list):
        errors.append("Actionable notes must be a list")
        return errors
    if len(notes) < 3:
        errors.append(f"Need at least 3 actionable notes, got {len(notes)}")
        return errors
    for i, note in enumerate(notes):
        if not isinstance(note, str) or len(note.strip()) < 10:
            errors.append(f"Note {i+1} is too short or not a string")
    return errors

def validate_data_gaps(gaps, series):
    errors = []
    if not isinstance(gaps, list):
        errors.append("Data gaps must be a list")
        return errors
    missing_in_series = [s["id"] for s in series if s.get("value") is None]
    stale_in_series = []
    for s in series:
        if s.get("freq") == "quarterly" and s.get("timestamp"):
            try:
                ts = datetime.strptime(s["timestamp"], "%Y-%m-%d")
                if (datetime.now() - ts).days > 90:
                    stale_in_series.append(s["id"])
            except:
                pass
    if len(gaps) == 0 and (missing_in_series or stale_in_series):
        errors.append(f"Data gaps should report missing/stale: missing={missing_in_series}, stale={stale_in_series}")
    return errors

def grade(scenario_file, output_file):
    results = {"passed": False, "errors": [], "warnings": []}
    try:
        thresholds = load_thresholds()
        series, asof = load_input(scenario_file)
        output = json.loads(Path(output_file).read_text())
        required_keys = {"signal_board", "composite_risk_light", "actionable_notes", "data_gaps"}
        missing_keys = required_keys - set(output.keys())
        if missing_keys:
            results["errors"].append(f"Missing top-level keys: {missing_keys}")
            return results
        results["errors"].extend(validate_signal_board(output.get("signal_board", []), thresholds))
        results["errors"].extend(validate_composite_risk(output, series, thresholds))
        results["errors"].extend(validate_actionable_notes(output.get("actionable_notes", [])))
        results["errors"].extend(validate_data_gaps(output.get("data_gaps", []), series))
        results["passed"] = len(results["errors"]) == 0
    except Exception as e:
        results["errors"].append(f"Fatal error: {str(e)}")
    return results

def main():
    if len(sys.argv) < 3:
        print("Usage: python grader.py <input_file> <output_file>")
        sys.exit(1)
    result = grade(sys.argv[1], sys.argv[2])
    print(json.dumps(result, indent=2))
    sys.exit(0 if result["passed"] else 1)

if __name__ == "__main__":
    main()
ENDOFFILE
